import os
import pandas as pd
from pathlib import Path

# List files in the current directory to see what's available
print("Files in current directory:")
for file in os.listdir('.'):
    if file.endswith('.pdf') or file.endswith('.txt') or file.endswith('.docx'):
        print(f"  - {file}")

# Check for policy documents
policy_files = []
for file in os.listdir('.'):
    if 'policy' in file.lower() or 'Policy' in file:
        policy_files.append(file)

print(f"\nFound {len(policy_files)} policy files:")
for file in policy_files:
    print(f"  - {file}")

# If no policy files found, search more broadly
if not policy_files:
    print("\nSearching for any document files...")
    for file in os.listdir('.'):
        if file.endswith(('.pdf', '.txt', '.docx', '.doc', '.md')):
            print(f"  - {file}")
